@js:
var r = '';
try {
    var m = src.match(/id="crypto-content"[^>]*data-crypto="([^"]+)"/);
    var cm = src.match(/data-cid="([^"]+)"/);
    if (!m || !cm) {
        r = '未找到加密内容，可能需要登录或该章节已锁定';
    } else {
        // HTML 实体解码（quot, amp, lt, gt）
        var DQ = String.fromCharCode(34);
        var AMP = String.fromCharCode(38);
        var LT = String.fromCharCode(60);
        var GT = String.fromCharCode(62);
        var ENT_Q = '&' + 'quot;';
        var ENT_A = '&' + 'amp;';
        var ENT_L = '&' + 'lt;';
        var ENT_G = '&' + 'gt;';
        var cs = m[1].split(ENT_Q).join(DQ).split(ENT_A).join(AMP).split(ENT_L).join(LT).split(ENT_G).join(GT);
        var cd = JSON.parse(cs);
        var cid = cm[1];
        var og = String(source.bookSourceUrl).replace(/\/$/, '');

        // ===== 密钥图提取（BitmapFactory + ByteArrayInputStream 方案）=====
        // 方案说明：File 类被屏蔽，javax 图像库在 Android 实现不完整
        // 改用 ByteArrayInputStream（未被屏蔽）+ BitmapFactory（Android 原生）
        var kB = null;
        var keyUrl = og + '/api/stats/' + encodeURIComponent(cid) + '/favicon.ico';
        var tmpPath = java.downloadFile(keyUrl);
        if (!tmpPath || String(tmpPath).length === 0) {
            r = '密钥图下载失败：返回空路径';
        } else {
            try {
                // 用 ISO-8859-1 无损读取 PNG 二进制
                var keyStr = java.readTxtFile(String(tmpPath), 'ISO8859_1');
                if (!keyStr || String(keyStr).length < 100) {
                    r = '密钥图读取异常，长度：' + (keyStr ? String(keyStr).length : 0);
                } else {
                    var keyBytes = java.strToBytes(String(keyStr), 'ISO8859_1');
                    var bais = new Packages.java.io.ByteArrayInputStream(keyBytes);
                    var bitmap = Packages.android.graphics.BitmapFactory.decodeStream(bais);
                    if (bitmap !== null) {
                        var w = bitmap.getWidth();
                        var h = bitmap.getHeight();
                        if (w !== 100 || h !== 36) {
                            r = '密钥图尺寸异常：' + w + 'x' + h;
                        } else {
                            // getPixel 返回 ARGB int，R 通道在 bits 16-23
                            var rgb0 = bitmap.getPixel(0, 0);
                            var px0r = (rgb0 >> 16) & 0xFF;
                            if (px0r !== 0xAB) {
                                r = '密钥图魔术标记错误：' + px0r.toString(16);
                            } else {
                                // 从像素 1 开始提取 32 个像素的 R 通道（跳过像素 0 的魔术标记 0xAB）
                                // 网站用 getImageData(0,0,8,5) 获取 8x5 网格，像素按行排列
                                // 像素 N 的坐标：x = N % 8, y = Math.floor(N / 8)
                                var hex = '';
                                for (var i = 1; i <= 32; i++) {
                                    var px = i % 8;
                                    var py = Math.floor(i / 8);
                                    var rgb = bitmap.getPixel(px, py);
                                    var b = (rgb >> 16) & 0xFF;
                                    hex += (b < 16 ? '0' : '') + b.toString(16);
                                }
                                if (hex.length === 64) {
                                    kB = java.hexDecodeToByteArray(hex);
                                } else {
                                    r = '密钥提取失败，hex长度：' + hex.length;
                                }
                            }
                        }
                    } else {
                        r = 'BitmapFactory 解码返回 null';
                    }
                }
            } catch(e) {
                r = 'BitmapFactory 解码失败：' + String(e);
            }
        }

        // ===== kB null 保护 + 解密流程 =====
        if (kB === null) {
            if (!r || r.length === 0) r = '密钥提取失败：kB 为空';
        } else {
            // 解密流程（v2 AES-CBC + v3 XOR 流解密）
            var b64ToBytes = function(b64) {
                var s = String(b64).replace(/-/g, '+').replace(/_/g, '/');
                while (s.length % 4) s += '=';
                return java.base64DecodeToByteArray(s);
            };
            var toStr = function(bytes) {
                return String(new Packages.java.lang.String(bytes, 'UTF-8'));
            };
            var Cipher = Packages.javax.crypto.Cipher;
            var SKS = Packages.javax.crypto.spec.SecretKeySpec;
            var IVS = Packages.javax.crypto.spec.IvParameterSpec;
            var Arrays = Packages.java.util.Arrays;
            var keySpec = new SKS(kB, 'AES');
            var ivB = b64ToBytes(cd.iv);
            var ivSpec = new IVS(ivB);
            var shuffled;
            if (cd.v === 3) {
                // v3 XOR 流解密
                var payloadB = b64ToBytes(cd.payload);
                var encryptedKey = Arrays.copyOfRange(payloadB, 0, 48);
                var xoredContent = Arrays.copyOfRange(payloadB, 48, payloadB.length);
                var cipher1 = Cipher.getInstance('AES/CBC/PKCS5Padding');
                cipher1.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
                var contentKey = cipher1.doFinal(encryptedKey);
                var Mac = Packages.javax.crypto.Mac;
                var mac = Mac.getInstance('HmacSHA256');
                mac.init(new SKS(kB, 'HmacSHA256'));
                mac.update(contentKey);
                var streamKey = mac.doFinal();
                var BAOS = Packages.java.io.ByteArrayOutputStream;
                var baos = new BAOS();
                var xoredLen = xoredContent.length;
                for (var i = 0; i < xoredLen; i++) {
                    var b = (xoredContent[i] & 0xff) ^ (streamKey[i % 32] & 0xff);
                    baos.write(b);
                }
                var rawText = toStr(baos.toByteArray());
                shuffled = rawText.split('\x02');
            } else {
                // v2 AES-CBC
                var cipher1 = Cipher.getInstance('AES/CBC/PKCS5Padding');
                cipher1.init(Cipher.DECRYPT_MODE, keySpec, ivSpec);
                var payloadB = b64ToBytes(cd.payload);
                var ds = toStr(cipher1.doFinal(payloadB));
                shuffled = JSON.parse(ds);
            }
            // 乱序还原
            var od = cd.order;
            var odIvB = b64ToBytes(od.i);
            var odIvSpec = new IVS(odIvB);
            var cipher2 = Cipher.getInstance('AES/CBC/PKCS5Padding');
            cipher2.init(Cipher.DECRYPT_MODE, keySpec, odIvSpec);
            var odDB = b64ToBytes(od.d);
            var os = toStr(cipher2.doFinal(odDB));
            os = String(os).replace(/[\x00-\x09\x0B\x0C\x0E-\x1F]/g, '').trim();
            var or = JSON.parse(os);
            var ro = [];
            for (var i = 0; i < or.length; i++) { ro[or[i]] = shuffled[i]; }
            var WM = '\u200B__WM__\u200B';
            for (var i = 0; i < ro.length; i++) {
                var p = ro[i];
                if (!p) continue;
                if (p.indexOf(WM) === 0) continue;
                if (p.indexOf('ifuwen') >= 0 && p.indexOf('com') >= 0) continue;
                r += '<p>' + p + '</p>';
            }
        }
    }
} catch(e) {
    r = '正文解密失败：' + e.toString();
}
result = r;

