@js:
var href = java.getString('@href');
var order = java.getString('@data-order') || java.getString('@data-chapter-id') || '';
var og = String(source.bookSourceUrl).replace(/\/$/, '');
if (href && href.indexOf('/novel/') === 0) {
    result = og + href;
} else {
    result = og + '/#locked-' + encodeURIComponent(order);
}

